(() => {'use strict';const $=id=>document.getElementById(id),g=()=>window.gameDebug;let current=null,pending=null,inflight=null,timer=null,failed=false,conflict=false,leaving=false,lastSaved='',serial=0,atMenu=false;
function button(text,fn,cls=''){const b=document.createElement('button');b.textContent=text;b.className=cls;b.type='button';b.onclick=fn;return b;}
async function api(path='',method='GET',body){const response=await fetch('/api/worlds'+path,{method,headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined,keepalive:method==='PUT'});let data;try{data=await response.json()}catch{throw Error('Сервер сохранений недоступен. Повторите попытку.')}if(!response.ok){const e=Error(data.error||'Ошибка сохранения мира.');Object.assign(e,data);throw e;}return data;}
function badge(text){const b=$('world-save');if(!b)return;b.textContent=text;b.hidden=!current;b.classList.toggle('save-error',failed||conflict);b.onclick=open;}
function capture(){if(!current||current.status!=='active'||leaving)return;const snap=JSON.stringify(g().state);if(snap===lastSaved||snap===pending)return;pending=snap;badge('Мир · есть изменения');clearTimeout(timer);timer=setTimeout(()=>flush(),450);}
async function flush(){clearTimeout(timer);if(inflight)return inflight;if(conflict)return false;if(!current||current.status!=='active'||!pending)return !failed;const epoch=serial;inflight=(async()=>{while(current?.status==='active'&&pending&&epoch===serial){const id=current.id,revision=current.revision,sent=pending;badge('Сохраняем мир…');try{const data=await api('/'+encodeURIComponent(id),'PUT',{revision,snapshot:JSON.parse(sent)});if(epoch!==serial)return true;current=data.world;lastSaved=sent;if(pending===sent)pending=null;failed=false;conflict=false;badge(pending?'Мир · есть изменения':'Мир сохранён');}catch(e){if(epoch!==serial)return false;failed=true;conflict=!!e.conflict;badge(e.message);g().render();open();return false;}}return true;})();const task=inflight;try{return await task;}finally{if(inflight===task)inflight=null;g().render();}}

async function exitToMenu(){if(g().moving||g().busy&&!window.Worlds.locked||window.HUD?.pending){message('Дождитесь завершения текущего действия.');return;}if(current?.status==='active'){capture();if(!await flush())return;}window.closeDialogue?.();document.querySelectorAll('dialog[open]').forEach(d=>d.close());atMenu=true;document.body.classList.toggle('at-main-menu',true);await window.Heroes.open();}
function detach(){serial++;clearTimeout(timer);current=null;pending=null;lastSaved='';failed=conflict=false;badge('');render();}
function attach(record){atMenu=false;document.body.classList.toggle("at-main-menu",false);serial++;clearTimeout(timer);current=record;pending=null;failed=conflict=false;leaving=true;g().loadWorld(record.snapshot);leaving=false;lastSaved=JSON.stringify(g().state);badge(record.status==='completed'?'Архив · мир завершён':'Мир сохранён');render();try{localStorage.setItem('last-world-id',record.id)}catch{}window.viewsDebug.switchTab('map');}
async function prepareLeave(){if(atMenu)return true;if(g().moving||g().busy&&!window.Worlds.locked||g().state.combat){message('Сначала завершите движение или бой. Мир можно закрыть и продолжить позже.');return false;}if(current?.status==='active'){capture();if(!await flush()){open();return false;}}return true;}
function message(text){$('modal-title').textContent='Миры';$('modal-body').textContent=text;$('modal').showModal();}
async function enterTest(h){if(!await prepareLeave())return;const wasMenu=atMenu;atMenu=false;document.body.classList.toggle("at-main-menu",false);detach();g().loadHero(h,wasMenu);$('heroes-panel').close();window.viewsDebug.switchTab('map');}
async function choose(h){if(!await prepareLeave())return;const d=$('modal');$('modal-title').textContent=h.name+' · Миры';$('modal-body').textContent='Загрузка…';$('heroes-panel').close();d.showModal();try{const {worlds}=await api('?hero_id='+encodeURIComponent(h.id));paintChoice(h,worlds);}catch(e){$('modal-body').textContent=e.message;$('modal-body').append(button('Повторить',()=>choose(h)));}}
function paintChoice(h,worlds){const body=$('modal-body');body.replaceChildren();const active=worlds.find(w=>w.status==='active'),p=document.createElement('p');p.textContent=active?'Герой связан с этим миром до завершения истории.':'Можно начать приключение этим героем. Сейчас доступна сценарная проба из двух локаций; ИИ-ведущий ещё не подключён.';body.append(p);if(active){const b=button('Продолжить · '+active.snapshot.world.title,async()=>{try{const data=await api('/'+active.id);attach(data.world);$('modal').close();}catch(e){message(e.message);}},'gold');body.append(b,button('Удалить этот мир',()=>removeWorld(h,active),'danger'));}else body.append(button('Начать мир',()=>create(h,worlds),'gold'));for(const w of worlds.filter(w=>w.status==='completed')){const details=document.createElement('details'),summary=document.createElement('summary');summary.textContent='Мир '+w.snapshot.world.chapter+' · '+w.snapshot.world.title+' · завершён';details.append(summary);const p=document.createElement('p');p.textContent='Уровень '+w.snapshot.level+' · '+w.snapshot.gold+' монет · посещено локаций: '+w.snapshot.world.discovered.length;details.append(p,button('Посмотреть хронику',()=>{const body=$('modal-body');$('modal-title').textContent='Архив мира';body.replaceChildren();for(const line of w.snapshot.logs){const p=document.createElement('p');p.textContent=line;body.append(p);}body.append(button('Вернуться к мирам',()=>{$('modal-title').textContent=h.name+' · Миры';paintChoice(h,worlds);}));}),button('Удалить мир из архива',()=>removeWorld(h,w),'danger'));body.append(details);}}
function removeWorld(h,w){const body=$('modal-body');$('modal-title').textContent='Удалить мир?';const p=document.createElement('p');p.textContent='Мир «'+w.snapshot.world.title+'» будет удалён навсегда. Герой останется с текущими характеристиками и снаряжением.';body.replaceChildren(p,button('Отмена',()=>choose(h)),button('Удалить мир',async()=>{try{if(!await prepareLeave())return;const record=current?.id===w.id?current:w;await api('/'+record.id,'DELETE',{revision:record.revision});if(current?.id===w.id){const checkpoint={...g().active(),level:g().state.level,xp:g().state.xp,gold:g().state.gold};detach();g().loadHero(checkpoint);}await window.Heroes.open();$('modal').close();}catch(e){p.textContent=e.message;}},'danger'));}
async function create(h,worlds,leaveGold=false){const latest=worlds[0];if(latest?.status==='completed'&&latest.snapshot.gold>0&&!leaveGold){const body=$('modal-body');body.replaceChildren();const p=document.createElement('p');p.textContent='Лимит переноса золота определим после настройки экономики. В этой пробе можно оставить всё золото в завершённом мире и перейти только с надетой экипировкой и предметами в руках. Содержимое рюкзака тоже останется в архиве.';body.append(p,button('Начать без переноса золота',()=>create(h,worlds,true),'gold'),button('Остаться пока здесь',()=>paintChoice(h,worlds)));return;}try{const {world}=await api('','POST',{heroId:h.id,leaveGold});attach(world);$('modal').close();}catch(e){message(e.message);}}
async function finish(){if(!current||current.status!=='active'||g().busy||g().state.combat)return;capture();if(!await flush())return;try{const {world}=await api('/'+current.id+'/finish','POST',{revision:current.revision});current=world;pending=null;badge('Архив · мир завершён');g().render();message('История завершена. Мир сохранён в архиве, герой свободен для следующего приключения. Откройте «Мои герои» → «Миры».');}catch(e){message(e.message);}}
async function reload(){if(!current)return;try{const {world}=await api('/'+current.id);attach(world);$('modal').close();}catch(e){message(e.message);}}
function open(){if(!current)return window.Heroes.open();const body=$('modal-body');$('modal-title').textContent=current.snapshot.world.title;body.replaceChildren();const p=document.createElement('p');p.textContent='Мир '+current.snapshot.world.chapter+' · '+(current.status==='completed'?'завершён':g().state.episode.stage==='done'?'история завершена':'история продолжается')+' · посещено '+g().state.world.discovered.length+' локаций';body.append(p,button('Хроника',()=>{ $('modal').close();g().journal(); }));if(current.status==='active'){body.append(button('Сохранить сейчас',async()=>{capture();await flush();}),button('Загрузить сохранение',reload));const b=button('Завершить мир',()=>{$('modal').close();finish();},'gold');b.disabled=g().state.episode.stage!=='done'||g().state.combat||g().busy;body.append(b);}if(failed||conflict){const p=document.createElement('p');p.className='creation-warning';p.textContent=conflict?'Другая вкладка изменила мир. Загрузите сохранение, чтобы продолжить.':'Изменения ещё не дошли до сервера. Повторите сохранение перед выходом.';body.append(p);}$('modal').showModal();}
async function workshop(){if(!await prepareLeave())return;atMenu=false;document.body.classList.toggle("at-main-menu",false);const a=structuredClone(g().active());detach();g().loadHero(a);viewsDebug.switchTab('test');}
function render(){document.body.classList.toggle('playing-world',!!current);document.body.classList.toggle('world-locked',!!current&&(current.status!=='active'||failed||conflict));if(!current)return;const s=g().state;if(s.world&&!s.world.discovered.includes(s.scene))s.world.discovered.push(s.scene);if($('scene-name'))$('scene-name').textContent=(s.scene==='hub'?'Часовня':'Крипта')+' · Мир '+s.world.chapter;const b=$('world-save');if(b)b.hidden=false;}
function init(){const b=button('Мир сохранён',open);b.id='world-save';b.hidden=true;b.className='world-save';$('scene-name').after(b);document.addEventListener('visibilitychange',()=>{if(document.hidden){capture();flush();}});window.addEventListener?.('pagehide',()=>{capture();flush();});}
window.Worlds={init,choose,enterTest,workshop,open,capture,flush,detach,attach,reload,finish,render,prepareLeave,exitToMenu,get atMenu(){return atMenu},get current(){return current},get locked(){return atMenu||!!current&&(current.status!=='active'||failed||conflict)},get pending(){return pending},get saving(){return !!inflight}};})();
